import{c as a,Q as e,j as i,m as s}from"./chunks/framework.DOi4mjdC.js";const m=JSON.parse('{"title":"PrintTimeStamp","description":"","frontmatter":{},"headers":[{"level":1,"title":"PrintTimeStamp","slug":"printtimestamp"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/基础API/调试接口/上板打印/PrintTimeStamp.md","filePath":"api/SIMD-API/基础API/调试接口/上板打印/PrintTimeStamp.md"}'),l={name:"api/SIMD-API/基础API/调试接口/上板打印/PrintTimeStamp.md"};function d(p,t,n,r,o,c){return e(),i("div",null,[...t[0]||(t[0]=[s(`<h1 id="printtimestamp" tabindex="-1">PrintTimeStamp <a class="header-anchor" href="#printtimestamp" aria-label="Permalink to &quot;PrintTimeStamp&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>√</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>√</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>√</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>x</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>推荐使用<a href="./../../../../Utils-API/调测接口/asc_time_stamp.html">asc_time_stamp</a>接口进行时间戳的获取，该接口同时适用于C语言和C++语言编程。</p><p>提供时间戳打点功能，用于在算子Kernel代码中标记关键执行点。调用后会打印如下信息：</p><ul><li><p>descId:用户自定义标识符，用于区分不同打点位置；</p></li><li><p>rsv ：保留值，默认为0，无需关注；</p></li><li><p>timeStamp :当前系统cycle数，用于计算时间差，时间换算规则可参考<a href="./../../系统变量访问/GetSystemCycle(ISASI).html">GetSystemCycle(ISASI)</a>；</p></li><li><p>pcPtr：pc指针数值，若无特殊需求，用户无需关注。</p></li><li><p>entry：算子开始执行的cycle数，若无特殊需求，用户无需关注。</p></li></ul><p>打印示例如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>descId is 11, rsv is 0, timeStamp is 815603975350485, pcPtr is 19792358553124, entry is 815603975328116.</span></span></code></pre></div><div class="caution custom-block github-alert"><p class="custom-block-title">注意</p><p>该功能主要用于<strong>调试和性能分析</strong>，开启后会对算子性能产生一定影响，<strong>生产环境建议关闭</strong>。 默认情况下，该功能关闭，开发者可以按需通过增加-DASCENDC_TIME_STAMP_ON编译选项的方式，开启打点功能。</p></div><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>__aicore__ inline void PrintTimeStamp(uint32_t descId)</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>descId</td><td>输入</td><td>用户自定义标识符（自定义数字），用于区分不同打点位置。 注意： [0, 0xffff]是预留给Ascend C内部各个模块使用的id值，用户自定义的descId建议使用大于0xffff的数值。</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li><p>该功能仅用于NPU上板调试。</p></li><li><p>暂不支持算子入图场景的打印。</p></li><li><p>单次调用本接口打印的数据总量不可超过1MB（还包括少量框架需要的头尾信息，通常可忽略）。使用时应注意，如果超出这个限制，则数据不会被打印。在使用自定义算子工程进行工程化算子开发时，一个算子所有使用Dump功能的接口在每个核上Dump的数据总量不可超过1MB。请开发者自行控制待打印的内容数据量，超出则不会打印。</p></li></ul><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AscendC::PrintTimeStamp(65577);</span></span></code></pre></div><p>打印结果如下（Dump信息头等仅在使用自定义算子工程时才会打印）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>opType=AddCustom, DumpHead: AIV-0, CoreType=AIV, block dim=8, total_block_num=8, block_remain_len=1047136, block_initial_space=1048576, rsv=0, magic=5aa5bccd</span></span>
<span class="line"><span>...// 一些框架内部的打点信息</span></span>
<span class="line"><span>descId is 65577, rsv is 0, timeStamp is 13806084506158, pcPtr is 20619064414544.</span></span></code></pre></div>`,22)])])}const u=a(l,[["render",d]]);export{m as __pageData,u as default};
